from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """- 撤退条件：\n  同行民兵が半数以下（端数切捨て）になった時、反応が【敵対的】であった場合のみ撤退する。\n- 捕虜報酬：指揮官を捕虜にした場合、戦利品に軍票+2枚される。タイラップを所持している場合は、このシナリオの記載をCore v1.01の一般規定より優先し、高脅威目標であるこの指揮官にも使用できる。捕虜を後送できるため、さらに軍票+3を得る。\n"""
new = """- 撤退条件：\n  同行民兵が半数以下（端数切捨て）になった時、反応が【敵対的】であった場合のみ撤退する。\n- 降伏交渉：\n  反応が【死ぬまで戦う】であっても、この指揮官はCore v1.01の【ネゴシエーション】の対象から除外されない。生命点が1になった場合、通常どおり【ネゴシエーション】を使用でき、成功すれば捕虜にできる。【死ぬまで戦う】は通常の撤退を行わないことを示すもので、【ネゴシエーション】による捕虜化を禁止しない。\n- 捕虜報酬：指揮官を捕虜にした場合、戦利品に軍票+2枚される。タイラップを所持している場合は、このシナリオの記載をCore v1.01の一般規定より優先し、高脅威目標であるこの指揮官にも使用できる。捕虜を後送できるため、さらに軍票+3を得る。\n"""
if s.count(old) != 1:
    raise SystemExit(f"event64 anchor count must be 1, got {s.count(old)}")
s = s.replace(old, new, 1)
scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 46. Black Sun 出目64【死ぬまで戦う】とネゴシエーション — 採用済み"
section = """

## 46. Black Sun 出目64【死ぬまで戦う】とネゴシエーション — 採用済み

ユーザー承認により、出目64【路地裏の指揮官】は反応が【死ぬまで戦う】であっても、Core v1.01の【ネゴシエーション】を使用可能とする。

- 【死ぬまで戦う】は通常の撤退を行わないことを示す反応として扱う。
- この指揮官を「狂信的な敵」等として【ネゴシエーション】無効にはしない。
- 指揮官の生命点が1になった場合、Core v1.01どおり【ネゴシエーション】を使用できる。
- 成功した場合は指揮官を【捕虜】にし、既存の【捕虜報酬】を適用できる。
- 反応が【敵対的】の場合の既存撤退条件、および【死ぬまで戦う】の場合に通常撤退しない処理は変更しない。

これにより、「撤退しない」と「降伏交渉に応じない」を別概念として扱い、出目64に用意された捕虜ルートを反応結果にかかわらず利用できるようにする。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
